SELECT CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, SUM(CASE WHEN brand = 'Umbrella' THEN price ELSE 0 END) AS umbrella_price, SORT_ARRAY(COLLECT_SET(category)) AS category_list FROM products GROUP BY launch_cohort HAVING MAX(price) < 470
